head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.SECUGRP_ID_EN = "EN";             // 증권그룹 ETN (원본 SECUGRP_ID_EN — pcc glb 에 없어 화면 상수, 선례 ULDSTF08035)
scwin.SECUGRP_NM_EN = "ETN";            // 증권그룹명 (원본 fn_getSecuGrpNm(SECUGRP_ID_EN) — pcc getSecuGrpNm 에 EN 없음)
scwin.SEARCH_TP_ISU = "1";              // 조회 구분 — 종목 (원본 rdo_ISUR_CD_1.CodeValue == "1")
scwin.SEARCH_TP_ISUR = "2";             // 조회 구분 — 발행회사 (원본 rdo_ISUR_CD_2.CodeValue == "1")
scwin.SRCH_DIV_ISU = "0";               // 명세 srchDivCd — 종목별 (원본 DIV_ETN_IDX_ADMISU_LIST_ISU)
scwin.SRCH_DIV_ISUR = "1";              // 명세 srchDivCd — 발행회사별 (원본 DIV_ETN_IDX_ADMISU_LIST_CORP)
scwin.SRCH_DIV_ALL = "2";               // 명세 srchDivCd — 전체 (원본 DIV_ETN_IDX_ADMISU_LIST_ALL)
scwin.SEL_TP_ISU = "1";                 // 팝업 선택 구분 — 종목 (원본 arrPar[7])
scwin.SEL_TP_ISUR = "2";                // 팝업 선택 구분 — 발행회사
scwin.SEL_TP_ALL = "3";                 // 팝업 선택 구분 — 전체
scwin.REGIST_TP_DESIGN = "0";           // 신규등록구분 — 관리종목지정
scwin.REGIST_TP_RELEAS = "4";           // 신규등록구분 — 관리종목지정 해제
scwin.LIST_STAT_DELISTED = "D";         // 상장상태 — 상장폐지(삭제 종목)
scwin.POPUP_PATH = "/ui/lst/etn/";      // 지정·해제·사유변경 팝업 배포 경로 (원본 ../etn/{ID}.gfm — 공통 계약서 §3, 결과서 §10 #6)
scwin.searchTp = "1";       // 현재 조회 구분 (SEARCH_TP_ISU · SEARCH_TP_ISUR)
scwin.isurCd = "";          // 종목 찾기에서 고른 종목의 발행기관코드 (원본 vIsurCd)
scwin.listStatCd = "Y";     // 종목 찾기에서 고른 종목의 상장상태 — D 면 신규·수정 금지 (원본 vLIST_STAT_CD)
// 팝업 정보 — 원본 CreateDialogFrame 의 제목·크기 (공통 계약서 §3.1)
scwin.POPUPS = {
    "ULDSTF08032" : { name : "관리종목지정", width : 720, height : 450 },
    "ULDSTF08032_new" : { name : "관리종목지정", width : 750, height : 450 },
    "ULDSTF08033" : { name : "관리종목지정 해제", width : 725, height : 600 },
    "ULDSTF08033_new" : { name : "관리종목지정 해제", width : 755, height : 595 },
    "ULDSTF08034" : { name : "관리종목지정 사유변경", width : 720, height : 680 }
};
// 관리종목지정업무구분(0 지정·1 사유변경·4 해제) → 종목 기준 팝업 (원본 fn_newpre_create_frame — 사유변경은 신규등록구분 콤보에 없어 더블클릭으로만 연다)
scwin.POPUP_BY_TP = { "0" : "ULDSTF08032", "1" : "ULDSTF08034", "4" : "ULDSTF08033" };
// 신규등록구분 → 발행회사 기준 신규 팝업 (원본 fn_new_create_frame)
scwin.POPUP_NEW_BY_TP = { "0" : "ULDSTF08032_new", "4" : "ULDSTF08033_new" };

// 원본 : /etn/ULDSTF08031.gfm (ETN 관리종목지정)
/*
 * 화면 동작
 *  - [종목] 또는 [발행회사] 중 하나를 골라 ETN 관리종목지정 내역을 조회한다.
 *    종목은 [종목 찾기]로 고른 뒤 [조회], 발행회사는 라디오를 고르거나 콤보를 바꾸면 바로 조회한다.
 *  - [신규]는 신규등록구분(지정·해제)에 따라 팝업을 연다 — 발행회사 기준이면 _new 판(08032_new·08033_new), 종목 기준이면 08032.
 *    종목 기준에서 해제를 고르면 지정 세부화면에서 해제하라고 안내한다.
 *  - 목록 더블클릭은 행의 관리종목지정업무구분(지정·사유변경·해제)에 맞는 팝업(08032·08034·08033)을 수정으로 연다.
 *  - 팝업이 저장했다고 돌려주거나 X 로 닫히면 다시 조회하고, 팝업이 [해제]·[사유변경]으로 다음 화면(next)을 돌려주면 다시 조회한 뒤 그 화면을 연다.
 *  - 상장폐지(삭제) 종목을 고르면 [신규]를 막고, 종목 기준 목록 더블클릭도 막는다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08031/ULDSTF08031.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08031.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 조회 구분을 종목으로, 신규등록구분을 지정으로 두고 조회 영역 Enter 키를 바인딩한다. 자동 조회는 하지 않는다(원본과 같음). (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 조회 구분 종목 (원본 rdo_ISUR_CD_1.CodeValue = "1")
    scwin.changeSearchTp(scwin.SEARCH_TP_ISU);

    // 2) 신규등록구분 첫 항목 (원본 cmb_RegistTyp index="0")
    cmb_RegistTyp.setValue(scwin.REGIST_TP_DESIGN);

    // 3) 조회 영역 Enter 키(규칙 22) — 입력란은 읽기 전용이지만 영역 포커스에서 조회한다
    $c.win.setEnterKeyEvent(pan_Cnd, scwin.btn_Search_onclick);

    // 4) 발행회사 콤보 — 원본 fn_get_isurcode(/etn/EtnCodeAct.do?method=listIsurCd&For=R)
    //    대응 API 가 명세에 없어 부르지 않는다 → 콤보는 "전체" 하나 (§10 #1)
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러) — 종목 기준이면 종목을 골랐는지 먼저 본다. (원본 img_Search onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        if (!(await scwin.validateSearch())) return;
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08031.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.rdo_ISUR_CD_1_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description [종목] 라디오 선택 — 조회 구분을 종목으로 바꾼다(발행회사 콤보는 전체로). 조회는 하지 않는다. (원본 rdo_ISUR_CD_1 OnClick → fn_changeRadioBtn(1))
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.rdo_ISUR_CD_1_onviewchange = function (info) {
    try {
        scwin.changeSearchTp(scwin.SEARCH_TP_ISU);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08031.rdo_ISUR_CD_1_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.rdo_ISUR_CD_2_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description [발행회사] 라디오 선택 — 조회 구분을 발행회사로 바꾸고(종목 비움) 바로 조회한다. (원본 rdo_ISUR_CD_2 OnClick → fn_changeRadioBtn(2) · fn_search)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.rdo_ISUR_CD_2_onviewchange = async function (info) {
    try {
        scwin.changeSearchTp(scwin.SEARCH_TP_ISUR);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08031.rdo_ISUR_CD_2_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.cmb_ISUR_CD_onviewchange
 * @author Inswave
 * @date 2026. 10. 30
 * @description 발행회사 콤보 변경 — 조회 구분을 발행회사로 바꾸고 바로 조회한다. (원본 cmb_ISUR_CD OnSelChange → fn_changeRadioBtn(2) · fn_search)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_ISUR_CD_onviewchange = async function (info) {
    try {
        scwin.changeSearchTp(scwin.SEARCH_TP_ISUR);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08031.cmb_ISUR_CD_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.btn_iSU_CD_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(돋보기) 버튼 클릭 (원본 btn_iSU_CD onclick → fn_PopFindEtnIsuAll + fn_SetParIsur)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_iSU_CD_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08031.btn_iSU_CD_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록 행 더블클릭 — 그 건을 관리종목지정업무구분에 맞는 팝업으로 연다. (원본 grd_List OnDblClick)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetail(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08031.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.img_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 엑셀다운로드 버튼 클릭 (원본 img_Excel onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_Excel_onclick = async function (e) {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08031.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_Regist_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 버튼 클릭 (원본 img_Regist onclick)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_Regist_onclick = async function (e) {
    try {
        await scwin.writeNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08031.img_Regist_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 관리종목지정 목록 조회 — 조회구분(종목별/발행회사별/전체)과 종목코드·발행기관코드를 보낸다.
 * (원본 fn_search — DIV_ETN_IDX_ADMISU_LIST_ISU/CORP/ALL, 공용 명세 §5 — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-list",
        ref : "dma_search",     // requestData { srchDivCd, isuCd, isurCd } (공용 명세 §5)
        target : "dlt_list=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러(원본 OnLoadError → alert_error)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 조회구분을 정해 목록을 조회하고 건수를 적은 뒤 행에 포커스한다. 업무처리번호를 주면 그 행으로, 없으면 마지막 행으로 간다.
 * (원본 fn_search + dts OnLoadCompleted — §6.1)
 * @param {String} keepBzProcsNo 조회 뒤 다시 고를 행의 업무처리번호(팝업이 닫힌 뒤 재조회용). 없으면 마지막 행
 * @returns
 * @hidden N
 */
scwin.search = async function (keepBzProcsNo) {
    // 조회구분 — 종목별 / 발행회사 콤보 "전체"면 전체, 아니면 발행회사별
    if (scwin.searchTp === scwin.SEARCH_TP_ISU) {
        dma_search.set("srchDivCd", scwin.SRCH_DIV_ISU);
    } else {
        dma_search.set("srchDivCd", $c.util.isEmpty(dma_search.get("isurCd")) ? scwin.SRCH_DIV_ALL : scwin.SRCH_DIV_ISUR);
    }

    // 조회 전 목록·건수를 비운다 — 조회가 실패하면 앞 조건의 행으로 팝업을 여는 일이 없도록
    dlt_list.removeAll();
    txb_TotCnt.setValue("0");

    if (!(await scwin.selectList())) return;

    txb_TotCnt.setValue(dlt_list.getRowCount());      // 원본 txb_TotCnt.value = "총건수 : " + rowcount
    scwin.focusRow(keepBzProcsNo);
};

/**
 * @method
 * @name scwin.focusRow
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 뒤 포커스할 행 — 업무처리번호가 같은 행, 없으면 마지막 행(원본 dts.RowPosition = rowcount). (§6.1)
 * @param {String} keepBzProcsNo 다시 고를 행의 업무처리번호
 * @returns
 * @hidden N
 */
scwin.focusRow = function (keepBzProcsNo) {
    const rowCount = dlt_list.getRowCount();
    if (rowCount === 0) return;

    let rowIndex = rowCount - 1;
    if (!$c.util.isEmpty(keepBzProcsNo)) {
        for (let i = 0; i < rowCount; i++) {
            if (dlt_list.getCellData(i, "bzProcsNo") === keepBzProcsNo) {
                rowIndex = i;
                break;
            }
        }
    }
    grd_List.setFocusedCell(rowIndex, "isuNm");
};

/**
 * @method
 * @name scwin.validateSearch
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 기준이면 종목을 골랐는지 본다. 안 골랐으면 MSG-0015 를 띄운다. (원본 img_Search·img_Regist onclick 의 공통 검사 — §6.1)
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
 */
scwin.validateSearch = async function () {
    if (scwin.searchTp === scwin.SEARCH_TP_ISU && $c.util.isEmpty(dma_search.get("isuCd"))) {
        // MSG-0015 "[종목코드(명)]을 선택해주세요."
        await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
        btn_iSU_CD.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.changeSearchTp
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 구분을 바꾸고 두 라디오를 맞춘다. 종목으로 가면 발행회사 콤보를 전체로, 발행회사로 가면 종목을 비우고 상장상태를 풀어 [신규]를 다시 쓸 수 있게 한다.
 * (원본 fn_changeRadioBtn(idx) — §6.2, 상장상태 해제는 §8 #3)
 * @param {String} searchTp 조회 구분 (SEARCH_TP_ISU · SEARCH_TP_ISUR)
 * @returns
 * @hidden N
 */
scwin.changeSearchTp = function (searchTp) {
    scwin.searchTp = searchTp;

    if (searchTp === scwin.SEARCH_TP_ISU) {
        dma_search.set("isurCd", "");       // 원본 cmb_ISUR_CD.index = 0
        rdo_ISUR_CD_1.setValue("1");
        rdo_ISUR_CD_2.setValue("");
    } else {
        dma_search.set("isuCd", "");        // 원본 txb_ISU_CD·txb_ISU_NM 비움
        txb_ISU_NM.setValue("");
        scwin.isurCd = "";
        scwin.setListStat("Y");
        rdo_ISUR_CD_1.setValue("");
        rdo_ISUR_CD_2.setValue("1");
    }
};

/**
 * @method
 * @name scwin.setListStat
 * @author Inswave
 * @date 2026. 10. 30
 * @description 고른 종목의 상장상태를 기억하고, 상장폐지(D)면 [신규]를 막는다. (원본 fn_SetParIsur 의 img_Regist disabled — §6.3)
 * @param {String} listStatCd 상장상태코드
 * @returns
 * @hidden N
 */
scwin.setListStat = function (listStatCd) {
    scwin.listStatCd = listStatCd ?? "";
    img_Regist.setDisabled(scwin.listStatCd === scwin.LIST_STAT_DELISTED);
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(ULDSTF92017_1 상장·비상장 종목약명 조회) — 고른 종목으로 조회 구분을 종목으로 바꾸고 종목코드·약명·발행기관코드·상장상태를 채운 뒤 조회한다. 취소·닫기면 그대로 둔다.
 * (원본 fn_GetParIsur/fn_SetParIsur + fn_PopFindEtnIsuAll(ULDSTF92017_2) — §6.3)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // TODO: 원본 ETN 종목약명 찾기 ULDSTF92017_2 는 미전환 — 전환된 92017_1(같은 계열, secugrpId 로 거름)로 연다 (§10 #4)
    const result = await $c.lc.popFindIsuAll({ secugrpId : scwin.SECUGRP_ID_EN });

    // 취소·닫기(X)는 반환이 없거나 { isCloseButtonClick } — 종목코드로 판정한다
    if ($c.util.isEmpty(result?.isuCd)) return;

    scwin.changeSearchTp(scwin.SEARCH_TP_ISU);
    dma_search.set("isuCd", result.isuCd);
    txb_ISU_NM.setValue(result.isuKorAbbrv ?? "");      // 원본 arrPar[0].ISU_KOR_ABBRV
    scwin.isurCd = result.isurCd ?? "";                  // 원본 vIsurCd = arrPar[0].ISUR_CD
    scwin.setListStat(result.listStatCd);                // 원본 vLIST_STAT_CD = arrPar[0].LIST_STAT_CD

    await scwin.search();
};

/**
 * @method
 * @name scwin.getPopupData
 * @author Inswave
 * @date 2026. 10. 30
 * @description 지정·해제·사유변경 팝업에 넘길 data. 신규는 업무처리번호·지정업무처리번호가 빈 값이고 구분코드는 신규등록구분, 수정은 더블클릭한 행 값을 쓴다.
 * (원본 fn_GetParNew / fn_GetParUpdate 의 arrPar[0..8] — 공통 계약서 §3.1, §6.4)
 * @param {Number} rowIndex 수정할 행(화면 번호). 신규면 -1
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getPopupData = function (rowIndex) {
    const isNew = (rowIndex < 0);
    const data = {
        isurCd : "",                                        // arr[0] 발행기관코드
        isurNm : "",                                        // arr[1] 발행기관명(종목 기준이면 종목약명)
        secugrpId : scwin.SECUGRP_ID_EN,                    // arr[2] 증권그룹
        mktId : $c.session.getUserInfo("market"),           // arr[3] 시장구분 (원본 fn_getMktId() — 로그인 사용자 시장)
        bzProcsNo : isNew ? "" : dlt_list.getCellData(rowIndex, "bzProcsNo"),                                    // arr[4] 업무처리번호 (신규는 없음)
        admisuDesignBzTpCd : isNew ? cmb_RegistTyp.getValue() : dlt_list.getCellData(rowIndex, "admisuDesignBzTpCd"),  // arr[5] 관리종목지정업무구분코드
        isuCd : "",                                         // arr[6] 종목코드
        selTp : "",                                         // arr[7] 선택 구분 1: 종목, 2: 발행회사, 3: 전체
        admisuDesignBzProcsNo : isNew ? "" : dlt_list.getCellData(rowIndex, "admisuDesignBzProcsNo")             // arr[8] 지정업무처리번호
    };

    if (scwin.searchTp === scwin.SEARCH_TP_ISU) {
        data.isurCd = isNew ? scwin.isurCd : dlt_list.getCellData(rowIndex, "isurCd");
        data.isurNm = txb_ISU_NM.getValue();
        data.isuCd = dma_search.get("isuCd");
        data.selTp = scwin.SEL_TP_ISU;
    } else if ($c.util.isEmpty(dma_search.get("isurCd"))) {
        // 발행회사 "전체" — 신규는 발행회사·종목을 비워 넘기고, 수정은 행의 발행회사·종목을 넘긴다
        data.isurCd = isNew ? "" : dlt_list.getCellData(rowIndex, "isurCd");
        data.isurNm = isNew ? "" : dlt_list.getCellData(rowIndex, "comNm");
        data.isuCd = isNew ? "" : dlt_list.getCellData(rowIndex, "isuCd");
        data.selTp = scwin.SEL_TP_ALL;
    } else {
        data.isurCd = isNew ? dma_search.get("isurCd") : dlt_list.getCellData(rowIndex, "isurCd");
        data.isurNm = isNew ? cmb_ISUR_CD.getText() : dlt_list.getCellData(rowIndex, "comNm");
        data.isuCd = isNew ? "" : dlt_list.getCellData(rowIndex, "isuCd");
        data.selTp = scwin.SEL_TP_ISUR;
    }
    return data;
};

/**
 * @method
 * @name scwin.openRegPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 팝업을 data 로 열고 닫힐 때까지 기다린다. 저장했다고 돌려주거나 X 로 닫히면 다시 조회하고(연 건의 행으로),
 * 팝업이 다음 화면(next : { id, data })을 돌려주면 다시 조회한 뒤 그 화면을 이어서 연다 — [해제]·[사유변경] 처럼 팝업이 형제 팝업으로 넘기는 경우.
 * (원본 fn_new_create_frame / fn_newpre_create_frame + 팝업의 형제 팝업 직접 호출 — 공통 계약서 §3.1·§3.2, §6.4)
 * @param {String} popupId 처음 열 팝업 id (scwin.POPUPS 의 키)
 * @param {Object} data 넘길 data (scwin.getPopupData)
 * @returns
 * @hidden N
 */
scwin.openRegPopup = async function (popupId, data) {
    let req = { id : popupId, data : data };

    while (req) {
        const info = scwin.POPUPS[req.id];
        if (!info) return;      // 계약 밖의 화면 id 는 열지 않는다

        const options = {
            id : req.id,
            popupName : scwin.SECUGRP_NM_EN + " " + info.name,
            width : info.width,
            height : info.height,
            type : "pageFramePopup"
        };
        const result = await $c.win.openPopup(scwin.POPUP_PATH + req.id + ".xml", options, req.data);

        const next = result?.next;
        // 원본은 팝업이 부모 fn_parentRefresh·fn_search 를 이름으로 불러 재조회했다 — 반환 규약으로 대신한다
        if (result?.isSaved === true || result?.isCloseButtonClick === true || next) {
            await scwin.search(req.data?.bzProcsNo);
        }
        req = (next && next.id) ? { id : next.id, data : next.data ?? {} } : null;
    }
};

/**
 * @method
 * @name scwin.writeNew
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 — 종목 기준이면 종목을 골랐는지, 해제를 고르지 않았는지 본다. 발행회사 기준이면 _new 판(08032_new·08033_new), 종목 기준이면 08032 를 연다.
 * 팝업을 연 뒤 신규등록구분은 지정으로 되돌린다. (원본 img_Regist onclick — §6.4)
 * @returns
 * @hidden N
 */
scwin.writeNew = async function () {
    const registTp = cmb_RegistTyp.getValue();

    if (scwin.searchTp === scwin.SEARCH_TP_ISU) {
        if (!(await scwin.validateSearch())) return;
        if (registTp === scwin.REGIST_TP_RELEAS) {
            await $c.win.alert("관리종목지정 세부화면에서 해제 해주시기 바랍니다.");
            return;
        }
    }

    const popupId = (scwin.searchTp === scwin.SEARCH_TP_ISUR) ? scwin.POPUP_NEW_BY_TP[registTp] : scwin.POPUP_BY_TP[registTp];
    if (!popupId) return;

    const data = scwin.getPopupData(-1);
    cmb_RegistTyp.setValue(scwin.REGIST_TP_DESIGN);      // 원본 cmb_RegistTyp.index = 0 (팝업을 연 직후)
    await scwin.openRegPopup(popupId, data);
};

/**
 * @method
 * @name scwin.openDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 — 종목 기준에서 상장폐지 종목이면 아무것도 하지 않고, 아니면 행의 관리종목지정업무구분(0 지정·1 사유변경·4 해제)에 맞는 팝업을 그 행 값으로 연다.
 * (원본 grd_List OnDblClick → fn_newpre_create_frame(ADMISU_DESIGN_BZ_TP_CD) — §6.4)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @returns
 * @hidden N
 */
scwin.openDetail = async function (rowIndex) {
    if (rowIndex < 0) return;
    // 삭제(상장폐지) 종목은 팝업 금지 (원본 jackal_11.05.12)
    if (scwin.searchTp === scwin.SEARCH_TP_ISU && scwin.listStatCd === scwin.LIST_STAT_DELISTED) return;

    const popupId = scwin.POPUP_BY_TP[dlt_list.getCellData(rowIndex, "admisuDesignBzTpCd")];
    if (!popupId) return;      // 원본 switch 에 없는 구분코드는 아무 화면도 열지 않았다

    await scwin.openRegPopup(popupId, scwin.getPopupData(rowIndex));
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 30
 * @description 목록을 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 GridToExcel(… "괸리종목지정내역", "", "8"), doLogSave 삭제 — §6.6)
 * @returns
 * @hidden N
 */
scwin.excelDown = async function () {
    await $c.data.downloadGridViewExcel(grd_List, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42) — 원본 오타 「괸리」 정정
        fileName : $c.win.getProgramId() + "_" + scwin.SECUGRP_NM_EN + "관리종목지정내역_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};
